import Animated from 'react-native-reanimated'
import {
	Text,
	TouchableOpacity,
	Pressable,
	TouchableWithoutFeedback
} from 'react-native'
import { Image as ExpoImage } from 'expo-image'
import { LinearGradient } from 'expo-linear-gradient'

export const AnimatedText = Animated.createAnimatedComponent(Text)
export const AnimatedTouchableOpacity =
	Animated.createAnimatedComponent(TouchableOpacity)
export const AnimatedTouchableWithoutFeedback =
	Animated.createAnimatedComponent(TouchableWithoutFeedback)
export const AnimatedPressable = Animated.createAnimatedComponent(Pressable)
export const AnimatedImage = Animated.createAnimatedComponent(ExpoImage)
export const AnimatedFlatList: typeof Animated.FlatList = Animated.FlatList
export const AnimatedLinearGradient =
	Animated.createAnimatedComponent(LinearGradient)
